}
test("unlisted: vllm retained, expires at original TTL even after repeated unlisted discoveries", async () => {
  let mode = "ok";
  await withClock((adv) => withEndpoint((req: any, res: any) => {
    if (req.url === "/v1/models") return json(res, { data: [mode === "ok" ? { id: "m", owned_by: "vllm", max_model_len: 8192 } : { id: "other" }] });
    if (req.url === "/version") return json(res, { version: "0.10.0" });
    res.statusCode = 404; res.end();
  }, async (ep) => {
    const c = new LocalLlmClient({ endpoint: `${ep}/v1`, model: "m" } as any);
    await c.discoverAdvertisement(); mode = "x";
    for (let i = 0; i < 4; i++) { adv(2 * 60_000); await c.discoverAdvertisement(); }
    assert.equal(c.getDetectedServerKind(), "vllm"); // 8 min
    adv(2 * 60_000 + 1);
    assert.equal(c.getDetectedServerKind(), "unknown");
  }));
});
