    await c.discoverAdvertisement(); assert.equal(c.getDetectedServerKind(), "gateway");
    phase = "404"; await c.discoverAdvertisement(); assert.equal(c.getDetectedServerKind(), "unknown");
    phase = "gw"; await c.discoverAdvertisement(); phase = "vllm"; adv(11 * 60_000);
    await c.chatCompletion(msg, []);
    assert.equal(c.getDetectedServerKind(), "vllm"); assert.deepEqual(hdr, [undefined]);
  }));
});
test("catalog-less endpoint: re-probes every minute forever? and slow probe blocks", async () => {
  let reads = 0, slow = 0;
  await withClock((adv) => withEndpoint((req: any, res: any) => {
    if (req.url === "/v1/models") { reads++; if (slow) return setTimeout(() => { res.statusCode = 404; res.end(); }, slow); res.statusCode = 404; return res.end(); }
    if (req.url === "/v1/chat/completions") return ok(res);
    res.statusCode = 404; res.end();
  }, async (ep) => {
    const c = new LocalLlmClient({ endpoint: `${ep}/v1`, model: "m" } as any);
    await c.discoverAdvertisement(); const base = reads;
    for (let i = 0; i < 5; i++) { adv(61_000); await c.chatCompletion(msg, []); }
    console.log("EXTRA /models reads over 5 minutes on catalog-less endpoint:", reads - base);
    slow = 1500; adv(61_000); const t = performance.now(); await c.chatCompletion(msg, []); console.log("blocked ms", Math.round(performance.now() - t));
  }));
});
test("concurrent same client no stampede; failing probe doesn't fail request", async () => {
  let reads = 0, fail = false;
  await withClock((adv) => withEndpoint((req: any, res: any) => {
    if (req.url === "/v1/models") { reads++; if (fail) { req.socket.destroy(); return; } return json(res, { data: [{ id: "m", limits_version: "1", context_length: 4096 }] }); }
    if (req.url === "/v1/chat/completions") return ok(res);
    res.statusCode = 404; res.end();
  }, async (ep) => {
    const c = new LocalLlmClient({ endpoint: `${ep}/v1`, model: "m" } as any);
    await c.discoverAdvertisement(); adv(11 * 60_000); const b = reads;
    await Promise.all([1,2,3,4,5].map(() => c.chatCompletion(msg, [])));
    console.log("concurrent reads:", reads - b);
    adv(11 * 60_000); fail = true; adv(61_000);
    const r = await c.chatCompletion(msg, []); assert.ok(r);
    const clients = [1,2,3].map(() => new LocalLlmClient({ endpoint: `${ep}/v1`, model: "m" } as any));
    fail = false; await clients[0].discoverAdvertisement(); for (const x of clients) (x as any).discoveredKeys.add((x as any).kindKey());
    adv(11*60_000); const b2 = reads; await Promise.all(clients.map((x) => x.chatCompletion(msg, []))); console.log("3 clients reads:", reads - b2);
  }));
});
